package com.wizzadrds.theworldremembers; import com.wizzadrds.theworldremembers.behavior.*; import com.wizzadrds.theworldremembers.home.*; import com.wizzadrds.theworldremembers.personality.*; import com.wizzadrds.theworldremembers.relationship.*; import com.wizzadrds.theworldremembers.stress.*; import org.junit.jupiter.api.Test; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*; class Phase4BehaviorAcceptanceTest { @Test void hostileNpcLeaves(){var r=new Relationship(UUID.randomUUID(),UUID.randomUUID(),0,0,0,0,0,50,0);var p=new PersonalityProfile(UUID.randomUUID(),java.util.Map.of());assertEquals(NpcDecision.LEAVE,new NpcBehaviorEngine().decide(NpcActivity.IDLE,new Relationship(r.npcId(),r.playerId(),0,0,0,50,0,0,0),p,new NpcStress(0)));} @Test void stressIsBounded(){var m=new NpcStress(UUID.randomUUID()); assertEquals(100,m.withValue(150).value()); assertEquals(0,m.withValue(-1).value());} }
